  Widget _sectionTitle(String t,String s)=>_SectionHeading(title:t,subtitle:s);
  Widget _demandSection(List<ActivityDemand> demands){final grouped=<String,List<ActivityDemand>>{};for(final d in demands){grouped.putIfAbsent('${d.activity}|${d.city}|${d.window}',()=>[]).add(d);}final groups=grouped.values.toList()..sort((a,b)=>b.length.compareTo(a.length));if(groups.isEmpty)return _quickStartStrip();return SizedBox(height:104,child:ListView.separated(scrollDirection:Axis.horizontal,itemCount:groups.take(6).length,separatorBuilder:(_,__)=>const SizedBox(width:7),itemBuilder:(context,i)=>_demandCard(groups[i].first,groups[i].length)));}
