class _SectionHeading extends StatelessWidget{final String title,subtitle;const _SectionHeading({required this.title,required this.subtitle});@override Widget build(BuildContext context)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:17,fontWeight:FontWeight.w900)),const SizedBox(height:1),Text(subtitle,style:const TextStyle(color:Colors.white38,fontSize:10.5))]);}
class _LiveDot extends StatefulWidget{const _LiveDot();@override State<_LiveDot> createState()=>_LiveDotState();}
class _LiveDotState extends State<_LiveDot> with SingleTickerProviderStateMixin{late final AnimationController _controller;@override void initState(){super.initState();_controller=AnimationController(vsync:this,duration:const Duration(milliseconds:1100))..repeat(reverse:true);}@override void dispose(){_controller.dispose();super.dispose();}@override Widget build(BuildContext context)=>FadeTransition(opacity:Tween<double>(begin:.35,end:1).animate(_controller),child:Container(width:7,height:7,decoration:const BoxDecoration(color:AppColors.cyan,shape:BoxShape.circle)));}
